select throws_ok($$select private.prepare_mcp_shift_update('18100000-0000-0000-0000-000000000002','18100000-0000-0000-0000-000000000008','2026-11-01 02:00+00','2026-11-01 03:00+00','[{"start_at":"2026-11-01T02:00:00Z","end_at":"2026-11-01T03:00:00Z","staffs":[{"staff_id":"18100000-0000-0000-0000-000000000099"}]}]')$$,'22023','invalid_shift_proposal','unknown staff rejected');
